//! Differential ratchet for `src/engine/battleScriptSetbideOpcode.ts`.
//! Expected complete projected outputs, typed controls, and the exact
//! missing-role error are generated by invoking the canonical TypeScript
//! handler; regenerate with `node --experimental-strip-types
//! core-rs/tools/gen-battle-script-setbide-vectors.mjs`.

use std::collections::BTreeSet;

use factory_core::battle_script_setbide::{
    apply_battle_script_setbide, BattleScriptSetbideBattlerState, BattleScriptSetbideControl,
    BattleScriptSetbideOutcome, BattleScriptSetbideRoles, BattleScriptSetbideRules,
    BATTLE_SCRIPT_SETBIDE_BATTLERS, BATTLE_SCRIPT_SETBIDE_BATTLER_COUNT,
    BATTLE_SCRIPT_STATUS2_BIDE, BATTLE_SCRIPT_STATUS2_BIDE_TURN_2,
    BATTLE_SCRIPT_STATUS2_MULTIPLETURNS,
};
use factory_core::battle_script_setbide_vectors_gen::{
    BattleScriptSetbideVectorCase, BattleScriptSetbideVectorState,
    BATTLE_SCRIPT_SETBIDE_BATTLER_DOMAIN, BATTLE_SCRIPT_SETBIDE_BIDE_COUNTER_INPUT_DOMAIN,
    BATTLE_SCRIPT_SETBIDE_BIDE_DAMAGE_EDGE_DOMAIN, BATTLE_SCRIPT_SETBIDE_BRANCH_CENSUS,
    BATTLE_SCRIPT_SETBIDE_CASES, BATTLE_SCRIPT_SETBIDE_CATEGORY_CENSUS,
    BATTLE_SCRIPT_SETBIDE_DOMAIN_CENSUS, BATTLE_SCRIPT_SETBIDE_STATUS2_EDGE_DOMAIN,
    BATTLE_SCRIPT_SETBIDE_U16_EDGE_DOMAIN, BATTLE_SCRIPT_SETBIDE_VECTOR_CORPUS_SHA256,
};

fn rules(value: BattleScriptSetbideVectorState) -> BattleScriptSetbideRules {
    BattleScriptSetbideRules {
        battlers: value
            .status2
            .map(|status2| BattleScriptSetbideBattlerState { status2 }),
        current_move: value.current_move,
        locked_moves: value.locked_moves,
        bide_dmg: value.bide_dmg,
        bide_targets: value.bide_targets,
        selector_roles: BattleScriptSetbideRoles {
            attacker: value.attacker,
            target: value.target,
            effect_battler: value.effect_battler,
            fainted: value.fainted,
        },
    }
}

fn vector_state(value: BattleScriptSetbideRules) -> BattleScriptSetbideVectorState {
    BattleScriptSetbideVectorState {
        status2: value.battlers.map(|battler| battler.status2),
        current_move: value.current_move,
        locked_moves: value.locked_moves,
        bide_dmg: value.bide_dmg,
        bide_targets: value.bide_targets,
        attacker: value.selector_roles.attacker,
        target: value.selector_roles.target,
        effect_battler: value.selector_roles.effect_battler,
        fainted: value.selector_roles.fainted,
    }
}

#[test]
fn complete_projected_outputs_controls_and_exact_missing_role_error_match_canonical_typescript() {
    assert_eq!(BATTLE_SCRIPT_SETBIDE_CASES.len(), 273);
    for (case_index, case) in BATTLE_SCRIPT_SETBIDE_CASES.iter().enumerate() {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptSetbideVectorCase) {
    let input = rules(case.initial);
    let before = input;
    let mut current = input;
    let mut actual_controls = Vec::new();
    let mut actual_error = None;

    for application in 0..case.applications {
        let prior = current;
        match apply_battle_script_setbide(&current) {
            Ok(outcome) => {
                actual_controls.push(outcome.control);
                assert_transition_shape(case_index, case, application, prior, outcome);
                if application > 0 {
                    assert_eq!(
                        outcome.rules, prior,
                        "case {case_index} {} application {application}: repeated Bide setup must be state-idempotent",
                        case.label,
                    );
                }
                current = outcome.rules;
            }
            Err(error) => {
                actual_error = Some(error.to_string());
                break;
            }
        }
    }

    assert_eq!(
        input, before,
        "case {case_index} {}: native transformation mutated input",
        case.label,
    );
    match (actual_error, case.expected, case.expected_error) {
        (None, Some(expected), None) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: canonical control sequence",
                case.label,
            );
            assert_eq!(
                actual_controls.len(),
                usize::from(case.applications),
                "case {case_index} {}: successful sequence stopped early",
                case.label,
            );
            assert_eq!(
                vector_state(current),
                expected,
                "case {case_index} {}: complete projected output",
                case.label,
            );
        }
        (Some(error), None, Some(expected_error)) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: error must not produce a control result",
                case.label,
            );
            assert_eq!(
                error, expected_error,
                "case {case_index} {}: exact missing-attacker error",
                case.label,
            );
        }
        (error, expected, expected_error) => panic!(
            "case {case_index} {}: generated outcome shape disagrees with native result: error={error:?}, expected={expected:?}, expected_error={expected_error:?}",
            case.label,
        ),
    }
}

fn assert_transition_shape(
    case_index: usize,
    case: &BattleScriptSetbideVectorCase,
    application: u8,
    prior: BattleScriptSetbideRules,
    outcome: BattleScriptSetbideOutcome,
) {
    assert_eq!(
        outcome.control,
        BattleScriptSetbideControl::Advance,
        "case {case_index} {} application {application}: Cmd_setbide must advance",
        case.label,
    );
    let attacker = prior.selector_roles.attacker.unwrap_or_else(|| {
        panic!(
            "case {case_index} {} application {application}: successful result had no attacker",
            case.label,
        )
    });
    let attacker_index = attacker.index();

    assert_eq!(
        outcome.rules.selector_roles, prior.selector_roles,
        "case {case_index} {} application {application}: changed selector roles",
        case.label,
    );
    assert_eq!(
        outcome.rules.current_move, prior.current_move,
        "case {case_index} {} application {application}: changed current move",
        case.label,
    );
    assert_eq!(
        outcome.rules.bide_targets, prior.bide_targets,
        "case {case_index} {} application {application}: changed saved Bide targets",
        case.label,
    );

    for battler in BATTLE_SCRIPT_SETBIDE_BATTLERS {
        let index = battler.index();
        if battler == attacker {
            assert_eq!(
                outcome.rules.battlers[index].status2,
                prior.battlers[index].status2
                    | BATTLE_SCRIPT_STATUS2_MULTIPLETURNS
                    | BATTLE_SCRIPT_STATUS2_BIDE_TURN_2,
                "case {case_index} {} application {application}: attacker status2 OR result",
                case.label,
            );
            assert_eq!(
                outcome.rules.battlers[index].status2
                    & !(BATTLE_SCRIPT_STATUS2_MULTIPLETURNS | BATTLE_SCRIPT_STATUS2_BIDE),
                prior.battlers[index].status2
                    & !(BATTLE_SCRIPT_STATUS2_MULTIPLETURNS | BATTLE_SCRIPT_STATUS2_BIDE),
                "case {case_index} {} application {application}: changed attacker status2 outside Bide bits",
                case.label,
            );
            assert_eq!(
                outcome.rules.locked_moves[index], prior.current_move,
                "case {case_index} {} application {application}: did not overwrite attacker locked move",
                case.label,
            );
            assert_eq!(
                outcome.rules.bide_dmg[index], 0,
                "case {case_index} {} application {application}: did not zero attacker Bide damage",
                case.label,
            );
        } else {
            assert_eq!(
                outcome.rules.battlers[index],
                prior.battlers[index],
                "case {case_index} {} application {application}: changed sibling status2 cell {}",
                case.label,
                battler.as_u8(),
            );
            assert_eq!(
                outcome.rules.locked_moves[index], prior.locked_moves[index],
                "case {case_index} {} application {application}: changed sibling locked move cell {}",
                case.label,
                battler.as_u8(),
            );
            assert_eq!(
                outcome.rules.bide_dmg[index], prior.bide_dmg[index],
                "case {case_index} {} application {application}: changed sibling Bide damage cell {}",
                case.label,
                battler.as_u8(),
            );
        }
    }

    assert_eq!(
        outcome.rules.battlers[attacker_index].status2 & BATTLE_SCRIPT_STATUS2_MULTIPLETURNS,
        BATTLE_SCRIPT_STATUS2_MULTIPLETURNS,
        "case {case_index} {} application {application}: attacker lacks STATUS2_MULTIPLETURNS",
        case.label,
    );
    assert_eq!(
        outcome.rules.battlers[attacker_index].status2 & BATTLE_SCRIPT_STATUS2_BIDE_TURN_2,
        BATTLE_SCRIPT_STATUS2_BIDE_TURN_2,
        "case {case_index} {} application {application}: attacker lacks Bide turn-two bit",
        case.label,
    );
}

#[test]
fn every_attacker_packed_status2_bide_counter_and_signed_damage_edge_is_retained() {
    let status_edges = BATTLE_SCRIPT_SETBIDE_CASES
        .iter()
        .filter(|case| case.category == "packed-status2-edge-matrix")
        .map(|case| {
            let attacker = case
                .initial
                .attacker
                .unwrap_or_else(|| panic!("status edge {} lacks attacker", case.label));
            (attacker.as_u8(), case.initial.status2[attacker.index()])
        })
        .collect::<BTreeSet<_>>();
    let expected_status_edges = BATTLE_SCRIPT_SETBIDE_BATTLER_DOMAIN
        .into_iter()
        .flat_map(|attacker| {
            BATTLE_SCRIPT_SETBIDE_STATUS2_EDGE_DOMAIN
                .into_iter()
                .map(move |status2| (attacker, status2))
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(status_edges, expected_status_edges);

    let counters = BATTLE_SCRIPT_SETBIDE_CASES
        .iter()
        .filter(|case| case.category == "repetition-state-idempotence")
        .map(|case| {
            let attacker = case
                .initial
                .attacker
                .unwrap_or_else(|| panic!("repetition case {} lacks attacker", case.label));
            (
                attacker.as_u8(),
                ((case.initial.status2[attacker.index()] & BATTLE_SCRIPT_STATUS2_BIDE) >> 8) as u8,
            )
        })
        .collect::<BTreeSet<_>>();
    let expected_counters = BATTLE_SCRIPT_SETBIDE_BATTLER_DOMAIN
        .into_iter()
        .flat_map(|attacker| {
            BATTLE_SCRIPT_SETBIDE_BIDE_COUNTER_INPUT_DOMAIN
                .into_iter()
                .map(move |counter| (attacker, counter))
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(counters, expected_counters);

    let damage_edges = BATTLE_SCRIPT_SETBIDE_CASES
        .iter()
        .filter(|case| case.category == "bide-damage-signed-i32-edge-matrix")
        .map(|case| {
            let attacker = case
                .initial
                .attacker
                .unwrap_or_else(|| panic!("damage edge {} lacks attacker", case.label));
            (attacker.as_u8(), case.initial.bide_dmg[attacker.index()])
        })
        .collect::<BTreeSet<_>>();
    let expected_damage_edges = BATTLE_SCRIPT_SETBIDE_BATTLER_DOMAIN
        .into_iter()
        .flat_map(|attacker| {
            BATTLE_SCRIPT_SETBIDE_BIDE_DAMAGE_EDGE_DOMAIN
                .into_iter()
                .map(move |damage| (attacker, damage))
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(damage_edges, expected_damage_edges);
}

#[test]
fn u16_overwrite_saved_target_and_all_selector_role_domains_are_pinned() {
    let move_matrix = BATTLE_SCRIPT_SETBIDE_CASES
        .iter()
        .filter(|case| case.category == "current-locked-u16-overwrite-matrix")
        .map(|case| {
            let attacker = case
                .initial
                .attacker
                .unwrap_or_else(|| panic!("move matrix {} lacks attacker", case.label));
            (
                attacker.as_u8(),
                case.initial.current_move,
                case.initial.locked_moves[attacker.index()],
            )
        })
        .collect::<BTreeSet<_>>();
    let expected_move_matrix = BATTLE_SCRIPT_SETBIDE_BATTLER_DOMAIN
        .into_iter()
        .flat_map(|attacker| {
            BATTLE_SCRIPT_SETBIDE_U16_EDGE_DOMAIN
                .into_iter()
                .flat_map(move |current_move| {
                    BATTLE_SCRIPT_SETBIDE_U16_EDGE_DOMAIN
                        .into_iter()
                        .map(move |locked_move| (attacker, current_move, locked_move))
                })
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(move_matrix, expected_move_matrix);

    let saved_targets = BATTLE_SCRIPT_SETBIDE_CASES
        .iter()
        .filter(|case| case.category == "saved-target-battler-preservation-matrix")
        .map(|case| {
            let attacker = case
                .initial
                .attacker
                .unwrap_or_else(|| panic!("saved target {} lacks attacker", case.label));
            (
                attacker.as_u8(),
                case.initial.bide_targets[attacker.index()].as_u8(),
            )
        })
        .collect::<BTreeSet<_>>();
    let expected_saved_targets = BATTLE_SCRIPT_SETBIDE_BATTLER_DOMAIN
        .into_iter()
        .flat_map(|attacker| {
            BATTLE_SCRIPT_SETBIDE_BATTLER_DOMAIN
                .into_iter()
                .map(move |saved_target| (attacker, saved_target))
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(saved_targets, expected_saved_targets);

    let selector_cases = BATTLE_SCRIPT_SETBIDE_CASES
        .iter()
        .filter(|case| case.category == "selector-role-preservation-matrix")
        .collect::<Vec<_>>();
    assert_eq!(selector_cases.len(), 20);
    let optional_values = selector_cases
        .iter()
        .flat_map(|case| {
            [
                case.initial.target.map(|battler| battler.as_u8()),
                case.initial.effect_battler.map(|battler| battler.as_u8()),
                case.initial.fainted.map(|battler| battler.as_u8()),
            ]
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(
        optional_values,
        BTreeSet::from([None, Some(0), Some(1), Some(2), Some(3)])
    );
}

#[test]
fn overwrite_preserve_repetition_and_missing_attacker_boundaries_are_explicit() {
    let boundaries = BATTLE_SCRIPT_SETBIDE_CASES
        .iter()
        .filter(|case| case.category == "overwrite-vs-preserve-boundaries")
        .collect::<Vec<_>>();
    assert_eq!(boundaries.len(), 4);
    let distinct = boundaries
        .iter()
        .find(|case| case.label == "overwrite_distinct_locked_move")
        .expect("distinct overwrite boundary");
    let distinct_expected = distinct.expected.expect("distinct overwrite output");
    assert_ne!(
        distinct.initial.locked_moves[0],
        distinct.initial.current_move
    );
    assert_eq!(
        distinct_expected.locked_moves[0],
        distinct.initial.current_move
    );
    let matching = boundaries
        .iter()
        .find(|case| case.label == "overwrite_matching_locked_move_value")
        .expect("matching overwrite boundary");
    let matching_expected = matching.expected.expect("matching overwrite output");
    assert_eq!(
        matching.initial.locked_moves[1],
        matching.initial.current_move
    );
    assert_eq!(
        matching_expected.locked_moves[1],
        matching.initial.current_move
    );

    let repeated = BATTLE_SCRIPT_SETBIDE_CASES
        .iter()
        .filter(|case| case.category == "repetition-state-idempotence")
        .collect::<Vec<_>>();
    assert_eq!(repeated.len(), 16);
    for case in repeated {
        assert_eq!(case.applications, 2, "{} applications", case.label);
        assert_eq!(
            case.controls,
            &[
                BattleScriptSetbideControl::Advance,
                BattleScriptSetbideControl::Advance,
            ],
            "{} controls",
            case.label,
        );
    }

    let missing = BATTLE_SCRIPT_SETBIDE_CASES
        .iter()
        .filter(|case| case.category == "missing-attacker-role")
        .collect::<Vec<_>>();
    assert_eq!(missing.len(), 5);
    for case in missing {
        assert_eq!(case.initial.attacker, None, "{} attacker", case.label);
        assert_eq!(case.expected, None, "{} output", case.label);
        assert!(case.controls.is_empty(), "{} control", case.label);
        assert_eq!(
            case.expected_error,
            Some("Battle Script hit-chain command requires a attacker role"),
            "{} exact error",
            case.label,
        );
    }
}

#[test]
fn fixed_domains_censuses_source_constants_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(BATTLE_SCRIPT_SETBIDE_BATTLER_COUNT, 4);
    assert_eq!(
        BATTLE_SCRIPT_SETBIDE_BATTLERS.map(|battler| battler.as_u8()),
        BATTLE_SCRIPT_SETBIDE_BATTLER_DOMAIN,
    );
    assert_eq!(BATTLE_SCRIPT_SETBIDE_BATTLER_DOMAIN, [0, 1, 2, 3]);
    assert_eq!(BATTLE_SCRIPT_SETBIDE_STATUS2_EDGE_DOMAIN.len(), 12);
    assert_eq!(
        BATTLE_SCRIPT_SETBIDE_BIDE_COUNTER_INPUT_DOMAIN,
        [0, 1, 2, 3]
    );
    assert_eq!(
        BATTLE_SCRIPT_SETBIDE_U16_EDGE_DOMAIN,
        [0x0000, 0x0001, 0x0075, 0x7fff, 0x8000, 0xffff],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETBIDE_BIDE_DAMAGE_EDGE_DOMAIN,
        [i32::MIN, -1, 0, 1, i32::MAX],
    );
    assert_eq!(BATTLE_SCRIPT_STATUS2_BIDE, 0x0000_0300);
    assert_eq!(BATTLE_SCRIPT_STATUS2_BIDE_TURN_2, 0x0000_0200);
    assert_eq!(BATTLE_SCRIPT_STATUS2_MULTIPLETURNS, 0x0000_1000);
    assert_eq!(
        BATTLE_SCRIPT_SETBIDE_DOMAIN_CENSUS,
        [
            ("battler-slots", 4),
            ("attacker-role-values", 4),
            ("optional-attacker-role-values", 5),
            ("other-selector-role-values", 5),
            ("selector-role-fields", 4),
            ("status2-u32-values", 4_294_967_296),
            ("status2-edge-values", 12),
            ("preexisting-bide-counter-inputs", 4),
            ("current-move-u16-values", 65_536),
            ("current-move-edge-values", 6),
            ("locked-move-u16-values", 65_536),
            ("locked-move-edge-values", 6),
            ("bide-damage-signed-i32-values", 4_294_967_296),
            ("bide-damage-edge-values", 5),
            ("saved-target-battler-values", 4),
            ("saved-target-array-cells", 4),
            ("application-count-values", 2),
            ("typed-missing-attacker-combinations", 5),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETBIDE_CATEGORY_CENSUS,
        [
            ("bide-damage-signed-i32-edge-matrix", 20),
            ("current-locked-u16-overwrite-matrix", 144),
            ("missing-attacker-role", 5),
            ("overwrite-vs-preserve-boundaries", 4),
            ("packed-status2-edge-matrix", 48),
            ("repetition-state-idempotence", 16),
            ("saved-target-battler-preservation-matrix", 16),
            ("selector-role-preservation-matrix", 20),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETBIDE_BRANCH_CENSUS,
        [
            ("advance", 252),
            ("advance-then-advance", 16),
            ("missing-attacker-role", 5),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETBIDE_VECTOR_CORPUS_SHA256,
        "ce9554d3269b3760cffc0605b69472636027f500f843303d0f05740c03f83234",
    );
}
